    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if the array is already strictly increasing
        is_strictly_increasing = True
        for i in range(n - 1):
            if nums[i] >= nums[i + 1]:
                is_strictly_increasing = False
                break

        if is_strictly_increasing:
            # If already strictly increasing, any subarray removal works
            # Number of subarrays = n*(n+1)//2
            return n * (n + 1) // 2

        # Find the longest prefix that is strictly increasing
        prefix_end = 0
        while prefix_end < n - 1 and nums[prefix_end] < nums[prefix_end + 1]:
            prefix_end += 1

        # Find the longest suffix that is strictly increasing
        suffix_start = n - 1
        while suffix_start > 0 and nums[suffix_start - 1] < nums[suffix_start]:
            suffix_start -= 1

        # Count incremovable subarrays
        count = 0

        # Case 1: Remove a suffix (keep prefix)
        # We can remove from position 0 to prefix_end+1
        # The prefix must be strictly increasing
        for i in range(prefix_end + 2):
            # Remove subarray from i to n-1
            # Keep elements from 0 to i-1
            if i == 0:
                # Remove entire array except prefix
                count += 1
            else:
                # Keep prefix ending at i-1
                if suffix_start > 0 and nums[i-1] < nums[suffix_start]:
                    count += 1

        # Case 2: Remove a prefix (keep suffix)
        # We can remove from 0 to suffix_start-1
