            # Remove subarray from 0 to j
            # Keep elements from j+1 to n-1
            if j == 0:
                # Remove first element
                count += 1
            else:
                # Keep suffix starting at j+1
                if prefix_end >= 0 and nums[prefix_end] < nums[j]:
                    count += 1

        # Case 3: Remove a middle subarray (keep prefix + suffix)
        # We need to ensure prefix_end < suffix_start
        # And nums[prefix_end] < nums[suffix_start]
        if prefix_end < suffix_start and nums[prefix_end] < nums[suffix_start]:
